  _ = `Auf Standard zurücksetzen`,
  _ = `Steuerung für Bildwiederholfrequenz externer Anzeigen zulassen`,
  _ = `FPS: Hoher Kontrast`,
  _ = `FPS in der Ecke anzeigen`,
  _ = `Nicht anzeigen`,
  _ = `Oben links`,
  _ = `Oben rechts`,
  _ = `Unten rechts`,
  _ = `Unten links`,
  _ = `Dynamische Bildwiederholfrequenz in Steam`,
